#include "/exercise/gigasecond/gigasecond.cpp"

using namespace boost::posix_time;
using namespace boost::gregorian;

static int fails = 0;
static void chk(const char* in, const char* exp) {
    ptime a = gigasecond::advance(time_from_string(in));
    ptime e = time_from_string(exp);
    bool ok = (a == e);
    if (!ok) ++fails;
    std::cout << (ok ? "PASS " : "FAIL ") << in << " -> " << a << " (expected " << exp << ")\n";
}

int main() {
    chk("2011-04-25 00:00:00", "2043-01-01 01:46:40");
    chk("1977-06-13 00:00:00", "2009-02-19 01:46:40");
    chk("1959-07-19 00:00:00", "1991-03-27 01:46:40");
    chk("2015-01-24 22:00:00", "2046-10-02 23:46:40");
    chk("2015-01-24 23:59:59", "2046-10-03 01:46:39");
    // leap-day boundary (2000 is a leap year, 1904 leap, 2100 not)
    chk("2000-02-29 12:00:00", "2031-11-07 13:46:40");
    // crosses month end and year end
    chk("1999-12-31 23:59:59", "2031-09-09 01:46:39");
    // far past date
    chk("0001-01-01 00:00:00", "0032-09-27 01:46:40");
    std::cout << (fails ? "EDGE FAILURES\n" : "ALL EDGE CASES PASS\n");
    return fails ? 1 : 0;
}
EOF
